 <canvas id="cinemaCanvas" aria-hidden="true"></canvas><div class="cinema-vignette"></div><div class="cinema-bar top"></div><div class="cinema-bar bottom"></div>
 <div class="cinema-controls"><button id="cinemaMute" aria-pressed="false">Son activé</button><button id="cinemaClose" autofocus>Retour au tableau ×</button></div>
