 <div class="cinema-stage"><div class="cinema-kicker" id="cinemaTournament"></div>
 <div class="cinema-trophy" aria-hidden="true"><svg viewBox="0 0 240 270" xmlns="http://www.w3.org/2000/svg"><defs><linearGradient id="cupMetal"><stop stop-color="#6a4418"/><stop offset=".16" stop-color="#d9a84c"/><stop offset=".37" stop-color="#fff0b0"/><stop offset=".51" stop-color="#a77023"/><stop offset=".72" stop-color="#e7be65"/><stop offset=".89" stop-color="#fff3bd"/><stop offset="1" stop-color="#9a6a29"/></linearGradient><linearGradient id="cupBase" x2="0" y2="1"><stop stop-color="#ffe9a2"/><stop offset=".25" stop-color="#d5a34d"/><stop offset=".5" stop-color="#725025"/><stop offset="1" stop-color="#d8b465"/></linearGradient><linearGradient id="cupDark"><stop stop-color="#13121a"/><stop offset=".5" stop-color="#38303a"/><stop offset="1" stop-color="#15131b"/></linearGradient></defs><ellipse cx="120" cy="255" rx="82" ry="8" fill="#e5ba55" opacity=".12"/><path d="M64 45H27v26q0 62 59 64M176 45h37v26q0 62-59 64" fill="none" stroke="url(#cupMetal)" stroke-width="12"/><path d="M65 38h110l-7 64q-6 45-48 60-42-15-48-60Z" fill="url(#cupMetal)" stroke="#f9d888" stroke-width="1"/><path d="M82 43h20l-3 66q1 21 12 36-27-17-29-49Z" fill="#fff7cc" opacity=".23"/><path d="m120 68 7 16 18 2-14 12 4 18-15-9-15 9 4-18-14-12 18-2Z" fill="#62451e" opacity=".8"/><path d="m120 69 6 16 18 1-14 12 4 17-14-9-14 9 4-17-14-12 18-1Z" fill="#ffeaa1" opacity=".72"/><path d="M110 157h20v30l14 20H96l14-20Z" fill="url(#cupMetal)"/><rect x="89" y="205" width="62" height="9" rx="3" fill="url(#cupMetal)"/><path d="M78 214h84l9 29H69Z" fill="url(#cupDark)" stroke="#bb914a"/><rect x="91" y="220" width="58" height="15" rx="2" fill="url(#cupMetal)"/><path d="M64 244h112v9H64Z" fill="url(#cupBase)"/><ellipse cx="120" cy="38" rx="55" ry="7" fill="#f2cf7d"/><ellipse cx="120" cy="37" rx="50" ry="4" fill="#533b1c"/><path d="M74 38h45" stroke="#fff6d4" stroke-width="2" opacity=".8"/></svg></div>
 <div class="cinema-word">Championne du tournoi</div><h1 class="cinema-name" id="cinemaName"></h1><div class="cinema-player" id="cinemaPlayer"></div><div class="cinema-recap" id="cinemaRecap"></div><div class="cinema-signature">Slot Arena · La victoire a un nom.</div></div><div class="cinema-progress"></div>
