<script id="embedded-state" type="application/json">null</script>
<script>
'use strict';
const ONLINE=true, BOOT=JSON.parse(document.getElementById('online-boot').textContent);let preparedAudio=null;
const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='slot-arena-v1:'+location.pathname, clone=o=>JSON.parse(JSON.stringify(o));
const uid=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2);
const fresh=()=>({schema:'slot-arena.v1',id:uid(),title:'Champions League des Slots',players:['Joueur 1','Joueur 2'],slots:[],order:'random',rounds:[],updatedAt:Date.now()});
let state=fresh(),history=[],diskHandle=null,diskQueue=Promise.resolve(),diskTimer,toastTimer,localOK=true;
const name=id=>state.slots.find(s=>s.id===id)?.name||'À déterminer';
const number=v=>{if(typeof v!=='string'||!v.trim())return null;const t=v.trim().replace(',','.');if(!/^\d+(\.\d+)?$/.test(t))return null;const n=Number(t);return Number.isFinite(n)&&n>=0&&n<=1e12?n:null};
function makeMatch(a=null,b=null){return{players:[a,b],scores:['',''],winner:null,bye:false}}
const owner=id=>state.slots.find(s=>s.id===id)?.owner??0;
const ownerBadge=id=>id?`<small class="owner-tag owner-${owner(id)}">${esc(state.players[owner(id)])}</small>`:'';
function bracketLayout(count){if(count===1)return[[1,0]];let a=Math.ceil(count/2),b=Math.floor(count/2);const layout=[[a,b]];while(a>1||b>1){a=Math.ceil(a/2);b=Math.ceil(b/2);layout.push([a,b])}layout.push([1,0]);return layout}
function matchSources(rounds,r,i,balanced){if(!balanced)return[i*2,i*2+1<rounds[r-1].length?i*2+1:null];if(r===rounds.length-1)return[0,1];const layout=bracketLayout(rounds[0].length),prev=layout[r-1],current=layout[r],right=i>=current[0],offset=right?prev[0]:0,index=offset+2*(right?i-current[0]:i),end=right?prev[0]+prev[1]:prev[0];return[index,index+1<end?index+1:null]}
function seedRounds(ids){const teams=[0,1].map(o=>ids.filter(id=>owner(id)===o));if(!teams[0].length||teams[0].length!==teams[1].length)throw Error('Il faut autant de slots pour chaque joueur.');state.bracket='balanced.v1';const rounds=bracketLayout(teams[0].length).map(([a,b])=>Array.from({length:a+b},()=>makeMatch()));rounds[0]=teams[0].map((id,i)=>makeMatch(id,teams[1][i]));sync(rounds,true);return rounds}
function sync(rounds=state.rounds,balanced=state.bracket==='balanced.v1'){for(let r=1;r<rounds.length;r++)for(let i=0;i<rounds[r].length;i++){const m=rounds[r][i],previous=rounds[r-1],[a,b]=matchSources(rounds,r,i,balanced),bye=b===null,p=[previous[a].winner,bye?null:previous[b].winner];if(m.players.some((v,k)=>v!==p[k])||m.bye!==bye){m.players=p;m.scores=['',''];m.winner=bye?p[0]:null;m.bye=bye}}}
function balanceState(s){if(s.bracket==='balanced.v1'||!s.rounds.length||s.rounds[0].some(m=>m.bye)||s.rounds.slice(1).flat().some(m=>(m.winner&&!m.bye)||m.scores.some(v=>v!=='')))return s;const first=s.rounds[0];s.rounds=bracketLayout(first.length).map(([a,b])=>Array.from({length:a+b},()=>makeMatch()));s.rounds[0]=first;s.bracket='balanced.v1';sync(s.rounds,true);return s}
function validState(s){if(!s||s.schema!=='slot-arena.v1'||typeof s.id!=='string'||typeof s.title!=='string'||s.title.length>80||!Number.isFinite(s.updatedAt)||!['random','list'].includes(s.order)||!Array.isArray(s.slots)||s.slots.length>128||!Array.isArray(s.rounds)||s.rounds.length>7)throw Error('Format de tournoi invalide.');
 const legacy=!s.players;if(legacy)s.players=['Joueur 1','Joueur 2'];if(!Array.isArray(s.players)||s.players.length!==2||s.players.some(n=>typeof n!=='string'||!n.trim()||n.length>40))throw Error('Joueurs invalides.');
 const ids=new Set();for(let i=0;i<s.slots.length;i++){const x=s.slots[i];if(legacy&&x)x.owner=i<Math.ceil(s.slots.length/2)?0:1;if(!x||typeof x.id!=='string'||ids.has(x.id)||typeof x.name!=='string'||!x.name.trim()||x.name.length>80||![0,1].includes(x.owner))throw Error('Liste de slots invalide.');ids.add(x.id)}
 if(s.bracket!==undefined&&s.bracket!=='balanced.v1')throw Error('Disposition invalide.');const balanced=s.bracket==='balanced.v1',layout=s.rounds.length&&balanced?bracketLayout(s.rounds[0].length):null;if(layout&&layout.length!==s.rounds.length)throw Error('Tours incohérents.');
 if(s.rounds.length){if(s.slots.length<2||s.rounds.at(-1).length!==1)throw Error('Tableau invalide.');const entered=[];
 for(let r=0;r<s.rounds.length;r++){const round=s.rounds[r];if(!Array.isArray(round)||!round.length||round.length>64||(balanced&&round.length!==layout[r][0]+layout[r][1])||(!balanced&&r&&round.length!==Math.ceil(s.rounds[r-1].length/2))||(r&&s.rounds[r-1].length===1))throw Error('Tour invalide.');
 for(let i=0;i<round.length;i++){const m=round[i];if(!m||!Array.isArray(m.players)||m.players.length!==2||!Array.isArray(m.scores)||m.scores.length!==2||typeof m.bye!=='boolean'||m.players.some(p=>p!==null&&!ids.has(p))||m.scores.some(v=>typeof v!=='string'||v.length>25))throw Error('Duel invalide.');
 let expectedBye=false;if(r===0){entered.push(...m.players.filter(Boolean));expectedBye=m.players[1]===null;if(!m.players[0])throw Error('Slot manquante.')}else{const[a,b]=matchSources(s.rounds,r,i,balanced);expectedBye=b===null;const p=[s.rounds[r-1][a].winner,expectedBye?null:s.rounds[r-1][b].winner];if(m.players.some((v,k)=>v!==p[k]))throw Error('Qualifications incohérentes.');}
 if(m.bye!==expectedBye)throw Error('Exemption invalide.');if(m.winner!==null&&!m.players.includes(m.winner))throw Error('Vainqueur invalide.');if(m.bye){if(m.winner!==m.players[0])throw Error('Exemption invalide.')}else if(m.winner!==null){const a=number(m.scores[0]),b=number(m.scores[1]);if(m.players.some(p=>!p)||a===null||b===null||(a>b&&m.winner!==m.players[0])||(b>a&&m.winner!==m.players[1]))throw Error('Résultat incohérent.');}}}
 if(entered.length!==ids.size||new Set(entered).size!==ids.size)throw Error('Participants incohérents.');}return balanceState(s)}
let loadWarning='';
function toast(t){$('toast').textContent=t;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4500)}
function checkpoint(){history.push(clone(state));if(history.length>40)history.shift();$('undo').disabled=false}
function localSave(){state.updatedAt=Date.now();try{localStorage.setItem(KEY,JSON.stringify(state));localOK=true;$('saveStatus').textContent='● Copie locale enregistrée · '+new Date().toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit',second:'2-digit'});$('saveStatus').style.color='var(--green)'}catch{localOK=false;$('saveStatus').textContent='⚠ Sauvegarde navigateur indisponible — exporte ton tournoi';$('saveStatus').style.color='var(--gold)'}if(diskHandle){clearTimeout(diskTimer);$('diskStatus').textContent='Écriture du fichier en attente…';diskTimer=setTimeout(writeDisk,250)}}
function writeDisk(){const handle=diskHandle,content=JSON.stringify(state,null,2);diskQueue=diskQueue.then(async()=>{if(!handle)return;try{const stream=await handle.createWritable();await stream.write(content);await stream.close();$('diskStatus').textContent='✓ Fichier mis à jour : '+handle.name+' · '+new Date().toLocaleTimeString('fr-FR')}catch{$('diskStatus').textContent='Écriture impossible. Réactive la sauvegarde fichier ou exporte ton tournoi.';diskHandle=null}})}
function roundName(i){const n=state.rounds[i].length;return n===1?'Finale':n===2?'Demi-finales':n===4?'Quarts de finale':n===8?'Huitièmes de finale':'Tour '+(i+1)}
function renderRoster(){const counts=[0,1].map(o=>state.slots.filter(s=>s.owner===o).length);$('count').textContent=counts.join(' v ');$('roster').innerHTML=state.players.map((p,o)=>`<section class="team team-${o}"><div class="team-head"><span class="team-dot"></span><input data-player="${o}" maxlength="40" value="${esc(p)}" aria-label="Nom du joueur ${o+1}"><span>${counts[o]}</span></div>${state.slots.filter(s=>s.owner===o).map((s,i)=>`<div class="roster-row"><span class="rank">${String(i+1).padStart(2,'0')}</span><input value="${esc(s.name)}" data-name="${esc(s.id)}" maxlength="80" aria-label="Slot ${i+1} de ${esc(p)}"><button class="remove" data-remove="${esc(s.id)}" aria-label="Supprimer ${esc(s.name)}">×</button></div>`).join('')||'<p class="small muted team-empty">Aucune slot pour le moment.</p>'}<button class="text" data-add-for="${o}">+ Ajouter pour ce joueur</button></section>`).join('');$('start').disabled=!counts[0]||counts[0]!==counts[1];$('balance').textContent=counts[0]===counts[1]&&counts[0]?counts[0]+' contre '+counts[1]+' · '+counts[0]+' duels au premier tour.':'Il faut autant de slots pour chaque joueur ('+counts.join(' / ')+').';$('start').textContent=state.rounds.length?'Refaire le tableau →':'Créer le tableau →';$('draw').value=state.order;updatePlayerOptions()}
function updatePlayerOptions(){Array.from($('addOwner').options).forEach((x,i)=>x.textContent=state.players[i])}
function matchFooter(m,r,i){if(m.bye)return m.winner?'Qualification automatique':'Qualification automatique à venir';if(m.winner)return`<span>✓ Duel terminé</span><button data-edit="${r},${i}">Corriger</button>`;if(m.players.some(p=>!p))return'En attente des qualifications';const a=number(m.scores[0]),b=number(m.scores[1]);if(a!==null&&b!==null&&a===b)return`<button data-win="${r},${i},0" title="Qualifier ${esc(name(m.players[0]))}">Égalité : 1re slot</button><button data-win="${r},${i},1" title="Qualifier ${esc(name(m.players[1]))}">Égalité : 2e slot</button>`;return`<button class="${a!==null&&b!==null?'primary':''}" data-win="${r},${i},auto" ${a===null||b===null?'disabled':''}>Valider le duel →</button>`}
function renderBoard(){const matches=state.rounds.flat(),eliminated=new Set(matches.filter(m=>m.winner&&!m.bye).flatMap(m=>m.players.filter(p=>p!==m.winner))),done=matches.filter(m=>m.winner&&!m.bye).length,total=state.slots.length?state.slots.length-1:0,champ=state.rounds.at(-1)?.[0]?.winner;let best=null;for(const m of matches)for(let i=0;i<2;i++){const n=number(m.scores[i]);if(n!==null&&(!best||n>best.n))best={n,id:m.players[i]}}$('stats').innerHTML=state.players.map((p,o)=>`<div class="stat team-stat owner-${o}"><strong>${state.slots.filter(s=>s.owner===o&&!eliminated.has(s.id)).length}<span> / ${state.slots.filter(s=>s.owner===o).length}</span></strong><span>${esc(p)} · en course</span></div>`).join('')+`<div class="stat"><strong>${state.slots.length}</strong><span>Slots inscrites</span></div><div class="stat"><strong>${done}<span style="font-size:18px"> / ${total}</span></strong><span>Duels terminés</span></div><div class="stat"><strong>${state.rounds.length||'—'}</strong><span>Tours</span></div><div class="stat"><strong>${best?'×'+best.n.toLocaleString('fr-FR'):'—'}</strong><span>Meilleur multiplicateur</span></div>`;$('champion').hidden=!champ;if(champ)$('champion').innerHTML=`<div class="cup">♛</div><div><small>Slot et joueur vainqueurs</small><strong>${esc(name(champ))}</strong><span class="champ-owner">${ownerBadge(champ)}</span><span class="muted small">Le dernier duel est remporté. Le tableau est complet.</span></div><button class="cinema-replay" data-replay>↻ Revivre la victoire</button>`;
$('bracket').innerHTML=state.rounds.length?state.rounds.map((round,r)=>`<section class="round"><h3>${roundName(r)} <span>${String(r+1).padStart(2,'0')}</span></h3><div class="matches">${round.map((m,i)=>`<article class="match ${m.winner?'done':''}"><div class="match-meta"><span>Duel ${r+1}.${i+1}</span><span>${m.bye?'Exemption':m.winner?'Validé':m.players.every(Boolean)?'À jouer':'À venir'}</span></div>${m.players.map((p,k)=>`<div class="player ${m.winner===p&&p?'winner':m.winner&&!m.bye?'loser':''}"><span class="name">${ownerBadge(p)}${p?esc(name(p)):m.bye?'Place libre':'À déterminer'}</span><div class="score-wrap"><input type="text" inputmode="decimal" maxlength="25" data-score="${r},${i},${k}" value="${esc(m.scores[k])}" placeholder="—" aria-label="Multiplicateur de ${esc(p?name(p):'la slot à venir')}, ${roundName(r)}, duel ${i+1}" ${m.winner||m.bye||m.players.some(x=>!x)?'disabled':''}></div></div>`).join('')}<div class="match-foot" id="foot-${r}-${i}">${matchFooter(m,r,i)}</div></article>`).join('')}</div></section>`).join(''):`<div class="empty"><div class="empty-symbol">1 VS 1</div><h2>Une seule slot au sommet.</h2><p>Chacun compose sa liste à gauche : 4 contre 4, 5 contre 5, 6 contre 6… Puis les slots s’affrontent jusqu’à la finale.</p><div class="steps"><span><b>01</b> Ajoute les slots</span><span><b>02</b> Saisis les multiplicateurs</span><span><b>03</b> Qualifie les gagnantes</span></div></div>`;organizeBoard()}
function organizeBoard(){
 const board=$('bracket');if(!state.rounds.length)return;
 const columns=Array.from(board.children),last=columns.length-1,left=[],right=[];
 for(let r=0;r<last;r++){const col=columns[r],cards=Array.from(col.querySelector('.matches').children),half=state.bracket==='balanced.v1'?bracketLayout(state.rounds[0].length)[r][0]:Math.min(cards.length,2**(last-r-1)),other=col.cloneNode(false);other.classList.add('right-half');other.innerHTML=col.querySelector('h3').outerHTML+'<div class="matches"></div>';cards.slice(half).forEach(c=>other.querySelector('.matches').append(c));left.push(col);right.unshift(other)}
 const final=columns[last];final.classList.add('final-round');const medal=document.createElement('div');medal.className='final-emblem';medal.innerHTML='<span>♛</span><small>UNE SEULE GAGNANTE</small>';final.querySelector('.matches').prepend(medal);board.replaceChildren(...left,final,...right);board.style.zoom=Number($('zoom').value)/100;
}
function render(){ $('title').value=state.title;$('undo').disabled=!history.length;renderRoster();renderBoard() }
function allowRoster(){return!state.rounds.length||confirm('Modifier les participantes effacera le tableau et ses résultats. Continuer ?')}
function add(names){const selectedOwner=Number($('addOwner').value);const clean=names.map(n=>n.trim()).filter(Boolean);if(!clean.length)return false;if(clean.some(n=>n.length>80)){toast('Chaque nom doit contenir au maximum 80 caractères.');return false}if(state.slots.length+clean.length>128){toast('Le tableau accepte au maximum 128 slots.');return false}if(!allowRoster())return false;checkpoint();state.rounds=[];clean.forEach(n=>state.slots.push({id:uid(),name:n,owner:selectedOwner}));save();render();return true}
$('addForm').onsubmit=e=>{e.preventDefault();if(add([$('slotName').value])){$('slotName').value='';$('slotName').focus()}};
$('bulkOpen').onclick=()=>$('bulkDialog').showModal();$('bulkAdd').onclick=()=>{if(add($('bulkText').value.split(/\r?\n/))){$('bulkText').value='';$('bulkDialog').close()}};document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());$('help').onclick=()=>$('helpDialog').showModal();
$('roster').addEventListener('focusin',e=>{if(e.target.dataset.name)e.target.dataset.before=e.target.value});
$('roster').addEventListener('input',e=>{if(e.target.dataset.player!==undefined){const v=e.target.value.trim();if(!v)return;if(e.target.dataset.history!=='yes'){checkpoint();e.target.dataset.history='yes'}state.players[+e.target.dataset.player]=v;updatePlayerOptions();save();renderBoard();return}const id=e.target.dataset.name;if(!id)return;const v=e.target.value.trim();if(!v)return;const s=state.slots.find(s=>s.id===id);if(e.target.dataset.history!=='yes'){checkpoint();e.target.dataset.history='yes'}s.name=v;save();renderBoard()});
$('roster').addEventListener('focusout',e=>{if(e.target.dataset.player!==undefined){e.target.value=state.players[+e.target.dataset.player];delete e.target.dataset.history}if(e.target.dataset.name){e.target.value=name(e.target.dataset.name);delete e.target.dataset.history}});
$('roster').addEventListener('click',e=>{const addButton=e.target.closest('[data-add-for]');if(addButton){$('addOwner').value=addButton.dataset.addFor;$('slotName').focus();return}const b=e.target.closest('[data-remove]');if(!b||!allowRoster())return;checkpoint();state.slots=state.slots.filter(s=>s.id!==b.dataset.remove);state.rounds=[];save();render()});
$('draw').onchange=()=>{checkpoint();state.order=$('draw').value;save()};$('title').onfocus=()=>{$('title').dataset.history=''};$('title').oninput=()=>{if(!$('title').dataset.history){checkpoint();$('title').dataset.history='yes'}state.title=$('title').value;save()};
$('start').onclick=()=>{if(!state.slots.length||state.slots.filter(s=>s.owner===0).length!==state.slots.filter(s=>s.owner===1).length){toast('Ajoute le même nombre de slots à chaque joueur.');return}if(state.rounds.length&&!confirm('Refaire le tableau effacera tous les résultats. Continuer ?'))return;checkpoint();const ids=state.slots.map(s=>s.id);if(state.order==='random')for(let i=ids.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[ids[i],ids[j]]=[ids[j],ids[i]]}state.rounds=seedRounds(ids);save();render();toast('Tableau prêt. Les duels peuvent commencer.')};
$('bracket').addEventListener('focusin',e=>{if(e.target.dataset.score)e.target.dataset.history=''});
$('bracket').addEventListener('input',e=>{const t=e.target;if(!t.dataset.score)return;const [r,i,k]=t.dataset.score.split(',').map(Number),m=state.rounds[r][i];if(m.winner)return;if(!t.dataset.history){checkpoint();t.dataset.history='yes'}const v=t.value.trim();t.setCustomValidity(v!==''&&number(v)===null?'Entre un multiplicateur positif ou nul (ex. 12,5).':'');t.style.borderColor=v!==''&&number(v)===null?'#ef9696':'';m.scores[k]=v;save();$('foot-'+r+'-'+i).innerHTML=matchFooter(m,r,i)});
$('bracket').addEventListener('change',e=>{if(e.target.dataset.score){const t=e.target;if(t.value!==''&&number(t.value)===null){t.reportValidity();const [r,i,k]=t.dataset.score.split(',').map(Number);state.rounds[r][i].scores[k]='';t.value='';t.setCustomValidity('');t.style.borderColor='';save();$('foot-'+r+'-'+i).innerHTML=matchFooter(state.rounds[r][i],r,i)}}});
$('bracket').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.edit){const[r,i]=b.dataset.edit.split(',').map(Number);if(!confirm('Rouvrir ce duel ? Les résultats des tours suivants qui en dépendent seront effacés.'))return;checkpoint();state.rounds[r][i].winner=null;sync();save();renderBoard()}if(b.dataset.win){const[r0,i0,w]=b.dataset.win.split(','),r=+r0,i=+i0,m=state.rounds[r][i],a=number(m.scores[0]),c=number(m.scores[1]);if(m.winner||m.bye||m.players.some(p=>!p)||a===null||c===null)return;const k=a===c?(w==='0'?0:w==='1'?1:null):a>c?0:1;if(k===null)return;checkpoint();m.winner=m.players[k];sync();save();renderBoard();if(r===state.rounds.length-1){$('cinemaMute').disabled=false;/* Start only after the shared server event. */}else toast(name(m.winner)+' se qualifie !')}});
$('undo').onclick=()=>{if(history.length){state=history.pop();save();render();toast('Dernière action annulée.')}};$('new').onclick=()=>{if((state.slots.length||state.rounds.length)&&!confirm('Créer un tournoi vide ? Pense à exporter le tournoi actuel pour le conserver.'))return;checkpoint();state=fresh();save();render()};
$('demo').onclick=()=>{if(state.slots.length&&!confirm('Remplacer le tournoi par un exemple ?'))return;checkpoint();state=fresh();state.title='Tournoi de démonstration';state.slots=['Slot Aurore','Slot Atlas','Slot Nova','Slot Eclipse','Slot Mirage','Slot Orion','Slot Comète','Slot Phoenix'].map((n,i)=>({id:uid(),name:n,owner:i<4?0:1}));state.rounds=seedRounds(state.slots.map(s=>s.id));save();render()};
function download(content,filename,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}
const filename=()=>((state.title||'Tournoi slots').replace(/[^a-zA-Z0-9À-ÿ _-]/g,'').trim().replace(/\s+/g,'_')||'Tournoi_slots');
$('export').onclick=()=>download(JSON.stringify(state,null,2),filename()+'.json','application/json');$('import').onclick=()=>$('importFile').click();$('importFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2000000)throw Error('Fichier trop volumineux.');const next=validState(JSON.parse(await file.text()));if(state.slots.length&&!confirm('Remplacer le tournoi affiché par celui du fichier ?'))return;checkpoint();state=next;save();render();toast('Tournoi restauré.')}catch(err){toast('Import impossible : '+err.message)}finally{e.target.value=''}};
$('copyHtml').onclick=()=>{const doc=document.documentElement.cloneNode(true);doc.querySelector('#embedded-state').textContent=JSON.stringify(state).replace(/</g,'\\u003c');doc.querySelectorAll('dialog').forEach(d=>d.removeAttribute('open'));doc.querySelector('#toast').setAttribute('hidden','');doc.querySelector('#victory').dataset.phase='';doc.querySelector('#victory').classList.remove('cinema-running');doc.querySelector('body').style.overflow='';download('<!doctype html>\n'+doc.outerHTML,filename()+'.html','text/html');toast('Copie HTML téléchargée avec ta progression.')};
$('disk').onclick=async()=>{if(!window.showSaveFilePicker){toast('Ce navigateur ne permet pas l’écriture automatique. Utilise Exporter ou la copie HTML.');return}try{diskHandle=await showSaveFilePicker({suggestedName:filename()+'.json',types:[{description:'Sauvegarde du tournoi',accept:{'application/json':['.json']}}]});clearTimeout(diskTimer);writeDisk();await diskQueue}catch(e){if(e.name!=='AbortError')toast('Sauvegarde fichier indisponible. Tu peux exporter le JSON.')}};
$('zoom').oninput=()=>{$('bracket').style.zoom=Number($('zoom').value)/100};
$('wide').onclick=()=>{document.body.classList.toggle('wide');$('wide').textContent=document.body.classList.contains('wide')?'↙ Vue normale':'⛶ Vue étendue'};
