// Finale: all effects are created only after a confirmed championship result.
let cinema=null;
function championship(){const final=state.rounds.at(-1)?.[0];return final&&final.winner&&!final.bye?final:null}
function stopCinema(){if(!cinema)return;const run=cinema;cinema=null;run.timers.forEach(clearTimeout);cancelAnimationFrame(run.raf);window.removeEventListener('resize',run.resize);if(run.audio)run.audio.close().catch(()=>{});$('enableSound').textContent='Activer le son de la finale';$('victory').classList.remove('cinema-running');$('victory').dataset.phase='';if($('victory').open)$('victory').close();document.body.style.overflow=run.overflow;run.focus?.focus?.()}
function scoreMusic(run){try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;const audio=preparedAudio&&preparedAudio.state!=='closed'?preparedAudio:new AC();preparedAudio=null;run.audio=audio;audio.resume().catch(()=>{});const master=audio.createGain();master.gain.value=.32;master.connect(audio.destination);run.master=master;
 const now=audio.currentTime+.06;function note(freq,start,duration,level,type='sine'){const osc=audio.createOscillator(),gain=audio.createGain(),filter=audio.createBiquadFilter();osc.type=type;osc.frequency.value=freq;filter.type='lowpass';filter.frequency.value=type==='triangle'?1400:5000;gain.gain.setValueAtTime(0,now+start);gain.gain.linearRampToValueAtTime(level,now+start+.12);gain.gain.exponentialRampToValueAtTime(.0001,now+start+duration);osc.connect(filter);filter.connect(gain);gain.connect(master);osc.start(now+start);osc.stop(now+start+duration+.1)}
 function boom(t){const osc=audio.createOscillator(),gain=audio.createGain();osc.frequency.setValueAtTime(110,now+t);osc.frequency.exponentialRampToValueAtTime(32,now+t+.7);gain.gain.setValueAtTime(.6,now+t);gain.gain.exponentialRampToValueAtTime(.0001,now+t+1.8);osc.connect(gain);gain.connect(master);osc.start(now+t);osc.stop(now+t+1.9)}
 const chords=[[146.83,220,293.66,349.23],[130.81,196,261.63,329.63],[174.61,261.63,349.23,440],[196,293.66,392,493.88],[130.81,196,261.63,329.63,523.25]];chords.forEach((ch,i)=>ch.forEach((f,k)=>note(f,[0,2.5,4.4,6,7.8][i],i===4?8:4,.07+(k===0?.035:0),'triangle')));[0,2.6,5.1,7.5].forEach(boom);[523.25,659.25,783.99,1046.5,783.99,1046.5].forEach((f,i)=>note(f,7.5+i*.35,4,.07));
 const buffer=audio.createBuffer(1,audio.sampleRate*3,audio.sampleRate),samples=buffer.getChannelData(0);for(let i=0;i<samples.length;i++)samples[i]=(Math.random()*2-1)*.25;const source=audio.createBufferSource(),filter=audio.createBiquadFilter(),gain=audio.createGain();source.buffer=buffer;filter.type='bandpass';filter.Q.value=.7;filter.frequency.setValueAtTime(150,now+2.3);filter.frequency.exponentialRampToValueAtTime(3500,now+5.2);gain.gain.setValueAtTime(0,now+2.3);gain.gain.linearRampToValueAtTime(.16,now+4.8);gain.gain.linearRampToValueAtTime(0,now+5.3);source.connect(filter);filter.connect(gain);gain.connect(master);source.start(now+2.3);source.stop(now+5.35);
 }catch{run.audio?.close().catch(()=>{});run.audio=null}}
function startCinema(){const final=championship();if(!final)return false;if(cinema)stopCinema();const winner=final.winner,winningScore=number(final.scores[final.players.indexOf(winner)]),wins=state.rounds.flat().filter(m=>m.winner===winner&&!m.bye).length,dialog=$('victory'),reduce=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
 const run={timers:[],raf:0,audio:null,master:null,muted:false,focus:document.activeElement,overflow:document.body.style.overflow,resize:()=>{}};cinema=run;
 $('cinemaName').textContent=name(winner);$('cinemaPlayer').textContent=state.players[owner(winner)];$('cinemaTournament').textContent=state.title||'Slot Arena';$('cinemaRecap').innerHTML=`<div><strong>×${winningScore?.toLocaleString('fr-FR')??'—'}</strong><small>En finale</small></div><div><strong>${wins}</strong><small>Duels gagnés</small></div><div><strong>${state.slots.length}</strong><small>Slots au départ</small></div>`;dialog.style.setProperty('--winner-color',owner(winner)===0?'#73d9ef':'#f295c6');dialog.dataset.phase='';dialog.classList.remove('cinema-finished');dialog.classList.add('cinema-running');$('cinemaMute').textContent='Son activé';$('cinemaMute').setAttribute('aria-pressed','false');$('cinemaIntro').textContent='Le dernier duel est joué.';document.body.style.overflow='hidden';dialog.showModal();
 function later(fn,t){run.timers.push(setTimeout(()=>{if(cinema===run)fn()},t))}
 if(reduce){dialog.dataset.phase='glory';dialog.classList.add('cinema-finished');$('cinemaMute').textContent='Son désactivé';run.muted=true;return true}
 scoreMusic(run);if(!run.audio)$('cinemaMute').textContent='Son indisponible';later(()=>dialog.dataset.phase='intro',80);later(()=>{dialog.dataset.phase='';},1900);later(()=>{$('cinemaIntro').textContent="Il n’en reste qu’une.";dialog.dataset.phase='intro'},2650);later(()=>dialog.dataset.phase='build',4400);later(()=>dialog.dataset.phase='reveal',6100);later(()=>dialog.dataset.phase='glory',8200);
 const canvas=$('cinemaCanvas'),ctx=canvas.getContext('2d');if(!ctx){later(()=>dialog.classList.add('cinema-finished'),17000);return true}let w=0,h=0;const stars=[],particles=[];run.resize=()=>{w=window.innerWidth;h=window.innerHeight;const ratio=Math.min(window.devicePixelRatio||1,1.5);canvas.width=w*ratio;canvas.height=h*ratio;ctx.setTransform(ratio,0,0,ratio,0,0)};run.resize();window.addEventListener('resize',run.resize);for(let i=0;i<95;i++)stars.push({x:Math.random(),y:Math.random(),r:Math.random()*1.6+.3,phase:Math.random()*6.28});
 function burst(x,y,count,style){for(let i=0;i<count;i++){const angle=Math.random()*Math.PI*2,speed=90+Math.random()*230;particles.push({x,y,vx:Math.cos(angle)*speed,vy:Math.sin(angle)*speed-80,life:3+Math.random()*4,max:7,size:1+Math.random()*3,spin:Math.random()*6.28,turn:(Math.random()-.5)*7,style,color:['#ffdfa0','#ba8c36','#fff4d1','#e7bf68'][i%4]})}}
 later(()=>{burst(w*.5,h*.45,125,'spark')},6100);later(()=>{burst(w*.15,h*.38,100,'confetti');burst(w*.85,h*.38,100,'confetti')},8300);later(()=>{burst(w*.25,h*.2,70,'spark');burst(w*.75,h*.2,70,'spark')},10800);
 const begin=performance.now();let previous=begin;
 function frame(now){if(cinema!==run)return;const seconds=(now-begin)/1000,dt=Math.min((now-previous)/1000,.04);previous=now;ctx.clearRect(0,0,w,h);const brightness=Math.min(1,seconds/5);ctx.save();for(const star of stars){const alpha=(.15+.25*(1+Math.sin(seconds*.7+star.phase)))*brightness;ctx.fillStyle=`rgba(237,207,138,${alpha})`;ctx.beginPath();ctx.arc(star.x*w,((star.y*h-seconds*7)%h+h)%h,star.r,0,Math.PI*2);ctx.fill()}ctx.restore();for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.life-=dt;if(p.life<=0){particles.splice(i,1);continue}p.vx*=Math.exp(-dt*.25);p.vy+=dt*(p.style==='spark'?46:65);p.x+=p.vx*dt;p.y+=p.vy*dt;p.spin+=p.turn*dt;ctx.save();ctx.globalAlpha=Math.min(1,p.life/1.8);ctx.translate(p.x,p.y);ctx.rotate(p.spin);ctx.fillStyle=p.color;if(p.style==='spark'){ctx.fillRect(-p.size/2,-p.size/2,p.size,p.size*2.5)}else{ctx.scale(Math.cos(p.spin),1);ctx.fillRect(-p.size,-p.size*2,p.size*2,p.size*4)}ctx.restore()}if(seconds<19)run.raf=requestAnimationFrame(frame);else{ctx.clearRect(0,0,w,h);dialog.classList.add('cinema-finished')}}
 run.raf=requestAnimationFrame(frame);later(()=>{run.audio?.close().catch(()=>{});run.audio=null;$('cinemaMute').textContent='Séquence terminée';$('cinemaMute').disabled=true},18000);return true}
$('cinemaClose').onclick=stopCinema;$('victory').addEventListener('cancel',e=>{e.preventDefault();stopCinema()});$('victory').addEventListener('close',()=>{if(cinema)stopCinema()});$('cinemaMute').onclick=()=>{if(!cinema)return;cinema.muted=!cinema.muted;if(cinema.master)cinema.master.gain.setTargetAtTime(cinema.muted?0:.32,cinema.audio.currentTime,.08);$('cinemaMute').textContent=cinema.muted?'Son coupé':'Son activé';$('cinemaMute').setAttribute('aria-pressed',String(cinema.muted))};$('champion').addEventListener('click',e=>{if(e.target.closest('[data-replay]')&&championship()){$('cinemaMute').disabled=false;startCinema()}});


let liveReady=false,liveRevision=0,liveDirty=false,liveSending=false,liveConflict=false,liveEdit=0,liveTimer=null,livePollTimer=null,livePollBusy=false,liveEvent=null,liveEventTimer=null,liveEventAt=0,liveFinalKey=null;
function liveStatus(message,error=false){$('saveStatus').textContent=message;$('saveStatus').style.color=error?'var(--gold)':'var(--green)'}
function liveMessage(message,conflict=false){$('liveMessage').textContent=message;$('liveMessage').classList.toggle('offline',!!message);if(conflict){const b=document.createElement('button');b.textContent='Exporter mes modifications puis recharger';b.onclick=()=>{$('export').click();location.reload()};$('liveMessage').append(b)}}
function applyRole(){document.body.classList.toggle('spectator',!BOOT.admin);$('liveRole').textContent=BOOT.admin?'Organisateur':'Spectateur · Lecture seule';if(!BOOT.admin){document.querySelectorAll('aside input,#title,#bracket input').forEach(i=>i.readOnly=true);document.querySelectorAll('[data-remove],[data-win],[data-edit],#start,#draw,#import,#new,#undo,#addOwner').forEach(b=>b.disabled=true)}}
const originalBoard=renderBoard;renderBoard=function(){originalBoard();applyRole()};const originalRoster=renderRoster;renderRoster=function(){originalRoster();applyRole()};
function save(){if(!BOOT.admin||!liveReady)return;localSave();liveEdit++;liveDirty=true;liveStatus('● Envoi des modifications…');clearTimeout(liveTimer);liveTimer=setTimeout(flushLive,300)}
function acceptEvent(event,serverNow,initial=false){const final=championship(),currentKey=final?state.id+':'+final.winner:null;
 if(!event||!final||event.champion!==final.winner||event.tournament!==state.id){clearTimeout(liveEventTimer);liveEventTimer=null;liveEventAt=0;liveFinalKey=null;if(cinema)stopCinema();return}
 if(liveFinalKey&&liveFinalKey!==currentKey&&cinema)stopCinema();liveFinalKey=currentKey;
 if(event.id===liveEvent)return;liveEvent=event.id;const age=serverNow-event.at;if((initial&&age>0)||age>15000)return;
 clearTimeout(liveEventTimer);liveEventAt=event.at;liveEventTimer=setTimeout(()=>{liveEventTimer=null;if(!championship()||state.id!==event.tournament||championship().winner!==event.champion)return;$('cinemaMute').disabled=false;startCinema()},Math.max(0,event.at-serverNow));
}
async function requestLive(options){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),10000);try{const response=await fetch('api.php',{cache:'no-store',credentials:'same-origin',signal:controller.signal,...options});let data;try{data=await response.json()}catch{throw new Error('Réponse serveur indisponible.')}if(!response.ok){const err=new Error(data.error||'Synchronisation indisponible.');err.status=response.status;throw err}return data}finally{clearTimeout(timer)}}
async function flushLive(){if(!BOOT.admin||!liveReady||liveSending||!liveDirty||liveConflict)return;liveSending=true;const edit=liveEdit,snapshot=clone(state);try{const data=await requestLive({method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':BOOT.csrf},body:JSON.stringify({revision:liveRevision,state:snapshot})});liveRevision=data.revision;if(edit===liveEdit){liveDirty=false;liveStatus('● Enregistré sur StratEdge · En direct');liveMessage('')}acceptEvent(data.event,data.serverNow,false)}catch(e){if(e.status===409||e.status===403||e.status===422){liveConflict=true;liveStatus('⚠ Modifications non synchronisées',true);liveMessage(e.message,true)}else{liveStatus('⚠ Hors ligne · Copie locale conservée',true);liveMessage('Connexion interrompue. Reconnexion automatique ; garde cette page ouverte.')}}finally{liveSending=false;if(liveDirty&&!liveConflict){clearTimeout(liveTimer);liveTimer=setTimeout(flushLive,1500)}}}
async function pollLive(initial=false){if(livePollBusy||liveSending||(BOOT.admin&&(liveDirty||liveConflict))){clearTimeout(livePollTimer);livePollTimer=setTimeout(()=>pollLive(!liveReady),1500);return}livePollBusy=true;try{const data=await requestLive();if(initial||data.revision!==liveRevision){state=data.state?validState(data.state):fresh();liveRevision=data.revision;history=[];render();acceptEvent(data.event,data.serverNow,initial)}if(initial){liveReady=true;document.body.classList.remove('online-loading')}liveStatus(BOOT.admin?'● Enregistré sur StratEdge · En direct':'● En direct · Mise à jour automatique');liveMessage('');if(!data.state&&!BOOT.admin)$('bracket').innerHTML='<div class="empty"><div class="empty-symbol">1 VS 1</div><h2>Le tournoi va commencer.</h2><p>L’organisateur prépare les slots. Le tableau apparaîtra automatiquement ici.</p></div>'}catch(e){liveStatus('⚠ Connexion en attente…',true);liveMessage('Connexion au tournoi indisponible. Nouvelle tentative automatique…')}finally{livePollBusy=false;clearTimeout(livePollTimer);livePollTimer=setTimeout(()=>pollLive(!liveReady),BOOT.admin?3000:1000)}}
$('shareLive').onclick=async()=>{const url=location.origin+'/tournoi-slots/';try{await navigator.clipboard.writeText(url);toast('Lien spectateur copié.')}catch{prompt('Lien spectateur à partager :',url)}};
$('enableSound').onclick=async()=>{try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)throw Error();if(!preparedAudio||preparedAudio.state==='closed')preparedAudio=new AC();await preparedAudio.resume();$('enableSound').textContent='✓ Son prêt pour la finale';toast('Son autorisé pour la finale.')}catch{toast('Le navigateur ne permet pas le son automatique. L’animation restera visible.')}};
window.addEventListener('online',()=>{if(liveDirty)flushLive();else pollLive(!liveReady)});
document.addEventListener('visibilitychange',()=>{if(!document.hidden){if(liveDirty)flushLive();else pollLive(!liveReady)}});
window.addEventListener('beforeunload',e=>{if(BOOT.admin&&liveDirty){e.preventDefault();e.returnValue=''}});
render();applyRole();pollLive(true);

